<script setup lang="ts">
import { ref } from 'vue'
import { customerServiceApi, customerServiceMessageApi, type CustomerRagIntent } from '../api/customer-rag'

const query=ref(''),intent=ref<CustomerRagIntent>('faq'),loading=ref(false),error=ref(''),result=ref<any>(null),messages=ref<any[]>([]),humanSessionId=ref(sessionStorage.getItem('customer_service_session_id')||''),humanStatus=ref(''),connectionState=ref<'connected'|'recovering'|'paused'>('connected'),conversationId=ref(sessionStorage.getItem('customer_service_conversation_id')||crypto.randomUUID()),poller=ref<number|undefined>(undefined)
sessionStorage.setItem('customer_service_conversation_id', conversationId.value)
async function refreshHuman(){if(!humanSessionId.value)return;try{messages.value=(await customerServiceMessageApi.messages(humanSessionId.value)).data.data||[];connectionState.value='connected'}catch{connectionState.value='recovering'}}
function startPolling(){ if(poller.value)return; poller.value=window.setInterval(async()=>{await refreshHuman()},2500) }
function closeHuman(){if(!humanSessionId.value)return; customerServiceMessageApi.customerClose(humanSessionId.value).then(()=>{humanSessionId.value='';sessionStorage.removeItem('customer_service_session_id');if(poller.value)window.clearInterval(poller.value);poller.value=undefined})}
const options:Array<{value:CustomerRagIntent;label:string}>= [{value:'company_info',label:'公司信息'},{value:'company_business',label:'公司业务'},{value:'faq',label:'常见问题'},{value:'workflow',label:'服务流程'},{value:'policy',label:'金融政策'},{value:'risk_public',label:'风险与资料规则'}]

async function ask(){
  const text=query.value.trim()
  if(!text||loading.value)return
  loading.value=true; error.value=''; result.value=null
  try { result.value=(await customerServiceApi.executePlan(text,conversationId.value)).data.data; if(result.value.customer_service_session_id){humanSessionId.value=result.value.customer_service_session_id;humanStatus.value=result.value.customer_service_session_status||'waiting_human';sessionStorage.setItem('customer_service_session_id',humanSessionId.value);startPolling()} }
  catch(e:any) { error.value=e.response?.data?.detail?.message||e.message||'客服服务暂时不可用' }
  finally { loading.value=false }
}
</script>
<template><section class="workspace-page"><div class="row-actions"><button class="button secondary" @click="$router.push('/customer-center')">返回客户中心</button></div><div class="section-heading"><div><span class="eyebrow">CUSTOMER SERVICE</span><h2 data-testid="customer-rag-title">智能客服</h2><p>实时账户问题先查询业务数据，公开知识问题再检索客服资料。</p></div></div><div class="panel-card"><select v-model="intent" class="advisor-select"><option v-for="item in options" :key="item.value" :value="item.value">{{item.label}}</option></select><textarea data-testid="customer-rag-input" v-model="query" placeholder="请输入您的问题"/><div class="row-actions"><button data-testid="customer-rag-send" class="button" :disabled="loading||!query.trim()" @click="ask">{{loading?'查询中…':'发送问题'}}</button></div></div><p v-if="connectionState!=='connected'" class="muted">{{connectionState==='paused'?'人工会话已暂停，客服重新接入后会继续。':'人工会话连接恢复中…'}}</p><p v-if="error" class="error">{{error}}</p><div v-if="humanSessionId" data-testid="customer-human-state" class="service-human-actions"><button class="button secondary" @click="closeHuman">结束人工服务</button><span>当前人工会话消息每 2.5 秒刷新</span></div><section v-if="result" class="panel-card"><span class="status-badge active">{{result.overall_status||result.evidence_status}}</span><span v-if="result.route" class="route-label">{{result.route}}</span><h3>客服回复</h3><p>{{result.answer||result.message}}</p><p v-if="result.clarification" class="muted">下一步：{{result.clarification}}</p><p v-if="result.next_action" class="muted">{{result.next_action}}</p><div v-if="result.results?.length" data-testid="customer-task-results" class="task-result-list"><h4>任务明细</h4><article v-for="task in result.results" :key="task.task_id" class="task-result-item"><div class="task-result-heading"><b>{{task.intent}}</b><span class="status-badge" :class="task.status">{{task.status}}</span></div><p v-if="task.answer">{{task.answer}}</p><p v-if="task.clarification" class="muted">{{task.clarification}}</p><small v-if="task.error" class="error">{{task.error}}</small></article></div><p v-if="result.ticket_no" class="success">已转人工客服，工单号：{{result.ticket_no}}。可在“我的工单”查看进度。</p><div v-if="result.data?.latest_asset" class="fact-grid"><div><small>总资产</small><b>{{Number(result.data.latest_asset.total_asset).toLocaleString()}}</b></div><div><small>现金余额</small><b>{{Number(result.data.latest_asset.cash_balance).toLocaleString()}}</b></div><div><small>可投资资产</small><b>{{Number(result.data.latest_asset.investable_asset).toLocaleString()}}</b></div></div><div v-if="result.data?.items?.length" class="fact-list"><h4>实时记录</h4><article v-for="item in result.data.items" :key="item.id"><b>{{item.ticket_no||item.order_no||item.name||item.product_name}}</b><span>{{item.status||item.market_value||''}}</span></article></div><div v-if="result.citations?.length"><h4>参考依据</h4><article v-for="item in result.citations" :key="item.chunk_id"><small>{{item.title_path||'知识库资料'}} · score {{Number(item.score).toFixed(2)}}</small><p>{{item.content}}</p></article></div></section></section></template>

